3	import ReconnectingWebSocket from "partysocket/ws";
4	import { useEffect, useState } from "react";
5	import { Logger } from "@/utils/Logger";
6	import { createPyodideConnection } from "../wasm/bridge";
7	import { isWasm } from "../wasm/utils";
8	import { BasicTransport } from "./transports/basic";
9	import type { IConnectionTransport } from "./transports/transport";
10	
11	interface UseConnectionTransportOptions {
12	  url: () => string;
13	  static: boolean;
14	  waitToConnect: () => Promise<void>;
15	  onOpen: (event: WebSocketEventMap["open"]) => void;
16	  onMessage: (event: WebSocketEventMap["message"]) => void;
17	  onClose: (event: WebSocketEventMap["close"]) => void;
18	  onError: (event: WebSocketEventMap["error"]) => void;
19	}
20	
21	// Per-`reconnect()` retry budget for partysocket. After exhaustion, partysocket
22	// stops silently; treat `retryCount >= MAX_RETRIES` as the give-up signal.
23	export const MAX_RETRIES = 10;
24	
25	function createConnectionTransport(
26	  options: Pick<UseConnectionTransportOptions, "url" | "static">,
27	): IConnectionTransport {
28	  if (options.static) {
29	    return BasicTransport.empty();
30	  }
31	  if (isWasm()) {
32	    return createPyodideConnection();
33	  }
34	  // Create a connection transport using the ReconnectingWebSocket from partysocket
35	  // This handles reconnecting when the connection is lost.
36	  const urlProvider = options.url; // We don't call the URL provider now since it may change (i.e. if the runtime redirects)
37	  // Cast needed: ReconnectingWebSocket types readyState as `number`
38	  // but IConnectionTransport expects `0 | 1 | 2 | 3`
39	  return new ReconnectingWebSocket(urlProvider, undefined, {
40	    maxRetries: MAX_RETRIES,
41	    debug: false,
42	    startClosed: true,
43	    // long timeout -- the server can become slow when many notebooks
44	    // are open.
45	    connectionTimeout: 10_000,
46	  }) as unknown as IConnectionTransport;
47	}
48	
49	/**
50	 * A hook for creating a connection transport with React.
51	 */
52	export function useConnectionTransport(options: UseConnectionTransportOptions) {
53	  const { onOpen, onMessage, onClose, onError, waitToConnect } = options;
54	
55	  // oxlint-disable-next-line react/hook-use-state
56	  const [transport] = useState<IConnectionTransport>(() => {
57	    const socket = createConnectionTransport(options);
58	
59	    socket.addEventListener("open", onOpen);
60	    socket.addEventListener("close", onClose);
61	    socket.addEventListener("error", onError);
62	    socket.addEventListener("message", onMessage);
63	
64	    return socket;
65	  });
66	
67	  useEffect(() => {
68	    // If it's closed, reconnect
69	    // This starts closed, so we need to connect for the first time
70	    if (transport.readyState === WebSocket.CLOSED) {
71	      void waitToConnect()
72	        .then(() => transport.reconnect())
73	        .catch((error) => {
74	          Logger.error("Healthy connection never made", error);
75	          transport.close();
76	        });
77	    }
78	
79	    return () => {
80	      Logger.warn(
81	        "useConnectionTransport is unmounting. This likely means there is a bug.",
82	      );
83	      transport.close();
84	      transport.removeEventListener("open", onOpen);
85	      transport.removeEventListener("close", onClose);
86	      transport.removeEventListener("error", onError);
87	      transport.removeEventListener("message", onMessage);
88	    };
89	    // oxlint-disable-next-line react-hooks/exhaustive-deps
90	  }, [transport]);
91	
92	  return transport;
93	}
