import ReconnectingWebSocket from "partysocket/ws";
import {
  type ConnectionEvent,
  type ConnectionTransportCallback,
  type IConnectionTransport,
} from "./transport";

// Per-`reconnect()` retry budget for partysocket. After exhaustion, partysocket
// stops retrying silently; treat `retryCount >= MAX_RETRIES` as the give-up
// signal.
export const MAX_RETRIES = 10;

// Sentinel close reason written by the transport when the retry budget is
// exhausted. Recognized by `classifyCloseEvent` as the terminal "gave-up"
// signal. It overrides any server-sent reason on the exhausting close event.
export const TRANSPORT_EXHAUSTED_REASON = "MARIMO_TRANSPORT_EXHAUSTED";

type AnyCallback = (event: unknown) => void;

/**
 * A WebSocket transport that wraps partysocket's reconnecting WebSocket and
 * intercepts close events.
 *
 * partysocket stops retrying silently once its retry budget is exhausted, which
 * makes it impossible for downstream consumers to distinguish "the socket gave
 * up" from a transient close. To surface that state, this transport rewrites the
 * close event's `reason` to {@link TRANSPORT_EXHAUSTED_REASON} once the inner
 * socket's `retryCount` reaches {@link MAX_RETRIES}. The rewrite applies even
 * when the original close event carries a server-sent reason.
 */
export class WsTransport implements IConnectionTransport {
  // The underlying reconnecting WebSocket. Exposed for advanced use (and tests)
  // via `(transport as any).inner`.
  inner: ReconnectingWebSocket;

  // Maps a user-provided callback to the wrapper actually registered on the
  // inner socket, keyed by event type. This lets us deduplicate registrations
  // and cleanly remove the internal wrapper on `removeEventListener`.
  private wrappers = new Map<string, Map<AnyCallback, AnyCallback>>();

  constructor(urlFactory: () => string) {
    this.inner = new ReconnectingWebSocket(urlFactory, undefined, {
      maxRetries: MAX_RETRIES,
      debug: false,
      startClosed: true,
      // long timeout -- the server can become slow when many notebooks
      // are open.
      connectionTimeout: 10_000,
    });
  }

  get readyState(): WebSocket["readyState"] {
    return this.inner.readyState as WebSocket["readyState"];
  }

  get retryCount(): number {
    return this.inner.retryCount;
  }

  reconnect(code?: number | undefined, reason?: string | undefined): void {
    this.inner.reconnect(code, reason);
  }

  close(): void {
    this.inner.close();
  }

  send(data: string | ArrayBuffer | Blob | ArrayBufferView): void {
    this.inner.send(data);
  }

  addEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    const cb = callback as unknown as AnyCallback;
    let forEvent = this.wrappers.get(event);
    if (!forEvent) {
      forEvent = new Map();
      this.wrappers.set(event, forEvent);
    }

    // Deduplicate: registering the same callback reference more than once must
    // only fire it once per event.
    if (forEvent.has(cb)) {
      return;
    }

    const wrapper: AnyCallback =
      event === "close"
        ? (e) => cb(this.maybeRewriteCloseEvent(e))
        : (e) => cb(e);

    forEvent.set(cb, wrapper);
    // Cast: the inner socket's event map is wider than ConnectionEvent.
    this.inner.addEventListener(
      event as keyof WebSocketEventMap,
      wrapper as EventListener,
    );
  }

  removeEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    const cb = callback as unknown as AnyCallback;
    const forEvent = this.wrappers.get(event);
    const wrapper = forEvent?.get(cb);
    if (!forEvent || !wrapper) {
      return;
    }
    // Remove the internal wrapper from the underlying socket so no orphaned
    // listeners remain.
    this.inner.removeEventListener(
      event as keyof WebSocketEventMap,
      wrapper as EventListener,
    );
    forEvent.delete(cb);
  }

  // Rewrites the close reason to TRANSPORT_EXHAUSTED_REASON when the inner
  // socket has exhausted its retry budget. Below the budget, the original event
  // is forwarded unchanged.
  private maybeRewriteCloseEvent(event: unknown): unknown {
    if (this.inner.retryCount < MAX_RETRIES) {
      return event;
    }

    const closeEvent = event as CloseEvent;
    try {
      return new CloseEvent("close", {
        code: closeEvent.code,
        reason: TRANSPORT_EXHAUSTED_REASON,
        wasClean: closeEvent.wasClean,
      });
    } catch {
      // Some environments reject the CloseEvent constructor (e.g. reserved
      // close codes). Fall back to a plain object exposing the fields
      // consumers read.
      return {
        type: "close",
        code: closeEvent.code,
        reason: TRANSPORT_EXHAUSTED_REASON,
        wasClean: closeEvent.wasClean,
      };
    }
  }
}
