 * A WebSocket transport that wraps partysocket's reconnecting WebSocket and
 * intercepts close events.
 *
 * partysocket stops retrying silently once its retry budget is exhausted, which
 * makes it impossible for downstream consumers to distinguish "the socket gave
 * up" from a transient close. To surface that state, this transport rewrites the
 * close event's `reason` to {@link TRANSPORT_EXHAUSTED_REASON} once the inner
 * socket's `retryCount` reaches {@link MAX_RETRIES}. The rewrite applies even
 * when the original close event carries a server-sent reason.
 */
export class WsTransport implements IConnectionTransport {
  // The underlying reconnecting WebSocket. Exposed for advanced use (and tests)
  // via `(transport as any).inner`.
  inner: ReconnectingWebSocket;

  // Maps a user-provided callback to the wrapper actually registered on the
  // inner socket, keyed by event type. This lets us deduplicate registrations
  // and cleanly remove the internal wrapper on `removeEventListener`.
  private wrappers = new Map<string, Map<AnyCallback, AnyCallback>>();

  constructor(urlFactory: () => string) {
    this.inner = new ReconnectingWebSocket(urlFactory, undefined, {
      maxRetries: MAX_RETRIES,
      debug: false,
      startClosed: true,
      // long timeout -- the server can become slow when many notebooks
      // are open.
      connectionTimeout: 10_000,
    });
  }

  get readyState(): WebSocket["readyState"] {
    return this.inner.readyState as WebSocket["readyState"];
  }

  get retryCount(): number {
    return this.inner.retryCount;
  }

  reconnect(code?: number | undefined, reason?: string | undefined): void {
    this.inner.reconnect(code, reason);
  }

  close(): void {
    this.inner.close();
  }

  send(data: string | ArrayBuffer | Blob | ArrayBufferView): void {
    this.inner.send(data);
  }

  addEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    const cb = callback as unknown as AnyCallback;
    let forEvent = this.wrappers.get(event);
    if (!forEvent) {
