import { describe, expect, it, vi } from "vitest";
import {
  MAX_RETRIES,
  TRANSPORT_EXHAUSTED_REASON,
  WsTransport,
} from "./ws";

class FakeSocket {
  retryCount = 0;
  readyState = 3;
  listeners = new Map<string, Set<(e: unknown) => void>>();
  addEventListener(type: string, cb: (e: unknown) => void) {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, new Set());
    }
    this.listeners.get(type)?.add(cb);
  }
  removeEventListener(type: string, cb: (e: unknown) => void) {
    this.listeners.get(type)?.delete(cb);
  }
  dispatch(type: string, e: unknown) {
    for (const cb of this.listeners.get(type) ?? []) {
      cb(e);
    }
  }
  count(type: string) {
    return this.listeners.get(type)?.size ?? 0;
  }
}

function make() {
  const t = new WsTransport(() => "ws://localhost/ws");
  const fake = new FakeSocket();
  // biome-ignore lint: test
  (t as any).inner = fake;
  return { t, fake };
}

describe("WsTransport scratch", () => {
  it("rewrites reason on exhaustion, overriding server reason", () => {
    const { t, fake } = make();
    const cb = vi.fn();
    t.addEventListener("close", cb);
    fake.retryCount = MAX_RETRIES;
    fake.dispatch("close", { code: 1000, reason: "server-said-bye" });
    expect(cb).toHaveBeenCalledTimes(1);
    expect(cb.mock.calls[0][0].reason).toBe(TRANSPORT_EXHAUSTED_REASON);
  });

  it("forwards original reason below budget", () => {
    const { t, fake } = make();
    const cb = vi.fn();
    t.addEventListener("close", cb);
    fake.retryCount = MAX_RETRIES - 1;
    fake.dispatch("close", { code: 1000, reason: "server-said-bye" });
    expect(cb.mock.calls[0][0].reason).toBe("server-said-bye");
  });

  it("dedups the same callback", () => {
    const { t, fake } = make();
    const cb = vi.fn();
    t.addEventListener("close", cb);
    t.addEventListener("close", cb);
    t.addEventListener("close", cb);
    expect(fake.count("close")).toBe(1);
    fake.dispatch("close", { code: 1000, reason: "" });
    expect(cb).toHaveBeenCalledTimes(1);
  });

  it("removes fully with a single call, no orphans", () => {
    const { t, fake } = make();
    const cb = vi.fn();
    t.addEventListener("close", cb);
    t.addEventListener("close", cb);
    t.removeEventListener("close", cb);
    expect(fake.count("close")).toBe(0);
    fake.dispatch("close", { code: 1000, reason: "" });
    expect(cb).not.toHaveBeenCalled();
  });

  it("delegates retryCount and readyState", () => {
    const { t, fake } = make();
    fake.retryCount = 7;
    fake.readyState = 1;
    expect(t.retryCount).toBe(7);
    expect(t.readyState).toBe(1);
  });
});
