  getSessionId: () => "sid" as SessionId,
}));

describe("runtime scratch", () => {
  it("formatHttpURL object arg", () => {
    const r = new RuntimeManager({ url: "https://example.com", lazy: true });
    const u = r.formatHttpURL({
      path: "api/test",
      searchParams: new URLSearchParams(),
      restrictToKnownQueryParams: false,
    });
    expect(u.pathname).toBe("/api/test");
  });

  it("probeHealth does NOT mutate config.url on redirect", async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      redirected: true,
      url: "https://sandbox.example.com/health",
    });
    const r = new RuntimeManager(
