    expect(r.httpURL.hostname).toBe("backend.example.com");
  });

  it("reconcileFromHealth mutates config.url on redirect, preserves query", async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      redirected: true,
      url: "https://sandbox.example.com/health?some_value=abc",
    });
    const r = new RuntimeManager(
      { url: "https://backend.example.com/lazy?some_value=abc", lazy: true },
      true,
    );
    const ok = await r.reconcileFromHealth();
    expect(ok).toBe(true);
    const ws = r.getWsURL("s" as SessionId);
    expect(ws.hostname).toBe("sandbox.example.com");
    expect(ws.pathname).toBe("/ws");
    expect(ws.searchParams.get("some_value")).toBe("abc");
    document.querySelectorAll("base").forEach((el) => el.remove());
  });

  it("probeHealth false on throw", async () => {
    global.fetch = vi.fn().mockRejectedValue(new Error("x"));
    const r = new RuntimeManager({ url: "https://example.com", lazy: true });
    expect(await r.probeHealth()).toBe(false);
  });
});
