import { describe, expect, it } from "vitest";
import { TRANSPORT_EXHAUSTED_REASON } from "./transports/ws";
import { WebSocketClosedReason, WebSocketState } from "./types";
import { classifyCloseEvent } from "./useMarimoKernelConnection";

describe("classifyCloseEvent scratch", () => {
  it("undefined reason -> retry", () => {
    expect(classifyCloseEvent({ reason: undefined })).toEqual({
      kind: "retry",
      status: { state: WebSocketState.CONNECTING },
    });
  });

  it("TRANSPORT_EXHAUSTED -> gave-up", () => {
