        code: WebSocketClosedReason.KERNEL_DISCONNECTED,
        reason: "kernel not found",
      },
    });
  });

  it("MARIMO_SHUTDOWN -> terminal", () => {
    const d = classifyCloseEvent({ reason: "MARIMO_SHUTDOWN" });
    expect(d.kind).toBe("terminal");
  });
});
